    time_t is_fake; time_t ft = get_fake(&is_fake);
    if (is_fake) {
        if (tv) { tv->tv_sec = ft; tv->tv_usec = 0; }
        return 0;
    }
    int (*real_gtod)(struct timeval*, void*) = dlsym(RTLD_NEXT, "gettimeofday");
    return real_gtod(tv, tz);
