import subprocess, time, datetime, re
def ts_for(h,m,s, day=13, mon=9, year=2026):
    import datetime
    dt = datetime.datetime(year,mon,day,h,m,s, tzinfo=datetime.timezone.utc)
    return int(dt.timestamp())

def count_moves(extra, duration=4.0, interval=0.5):
    subprocess.run(["tmux","kill-server"], capture_output=True)
    time.sleep(0.2)
    subprocess.run(["tmux","new-session","-d","-x","100","-y","30","-s","test"], capture_output=True)
    time.sleep(0.2)
    ts=ts_for(12,34,56)
    cmd=f"TERM=xterm LD_PRELOAD=/tmp/faketime.so FAKE_TIME={ts} ./executable -r {extra}"
    subprocess.run(["tmux","send-keys","-t","test",cmd,"Enter"], capture_output=True)
    time.sleep(1.0)
    def pos():
        out = subprocess.run(["tmux","capture-pane","-t","test","-p","-e"], capture_output=True, text=True)
        raw=out.stdout
        lines=raw.split('\n')
        for i,line in enumerate(lines):
            if '\x1b[4' in line:
                cells=[]
                bg=None
                j=0
                while j<len(line):
                    if line[j]=='\x1b' and j+1<len(line) and line[j+1]=='[':
                        k=line.find('m',j)
                        if k!=-1:
                            inner=line[j+2:k]
                            if inner in ('40','41','42','43','44','45','46','47'):
                                bg='G'
                            elif inner=='49':
                                bg=None
                            j=k+1
                            continue
                    elif line[j] in ('\x0e','\x0f'):
                        j+=1
                        continue
                    else:
                        cells.append((line[j],bg))
                        j+=1
                try:
                    first=min(idx for idx,(ch,b) in enumerate(cells) if b=='G')
                    return (i,first)
                except:
                    continue
        return None
    positions=[]
    start=time.time()
    while time.time()-start < duration:
        positions.append(pos())
        time.sleep(interval)
    # Count changes (moves)
    moves=0
    for a,b in zip(positions, positions[1:]):
        if a!=b:
            moves+=1
    print(f"extra {extra!r} positions {positions} moves={moves} in {duration}s")
    subprocess.run(["tmux","send-keys","-t","test","q"], capture_output=True)
    time.sleep(0.3)
    subprocess.run(["tmux","kill-server"], capture_output=True)

for extra in ["", "-d 1 -a 500000000", "-d 0 -a 500000000", "-d 0 -a 999999999", "-a 999999999", "-d 0 -a 1000000000"]:
    count_moves(extra, duration=3.5, interval=0.5)
