#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <time.h>
#include <locale.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>
#include <ncurses.h>

static const char *font[10][5] = {
    {"XXXXXX","XX  XX","XX  XX","XX  XX","XXXXXX"},
    {"    XX","    XX","    XX","    XX","    XX"},
    {"XXXXXX","    XX","XXXXXX","XX    ","XXXXXX"},
    {"XXXXXX","    XX","XXXXXX","    XX","XXXXXX"},
    {"XX  XX","XX  XX","XXXXXX","    XX","    XX"},
    {"XXXXXX","XX    ","XXXXXX","    XX","XXXXXX"},
    {"XXXXXX","XX    ","XXXXXX","XX  XX","XXXXXX"},
    {"XXXXXX","    XX","    XX","    XX","    XX"},
    {"XXXXXX","XX  XX","XXXXXX","XX  XX","XXXXXX"},
    {"XXXXXX","XX  XX","XXXXXX","    XX","XXXXXX"},
};

static void print_usage(void) {
    printf("usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] \n");
    printf("    -s            Show seconds                                   \n");
    printf("    -S            Screensaver mode                               \n");
    printf("    -x            Show box                                       \n");
    printf("    -c            Set the clock at the center of the terminal    \n");
    printf("    -C [0-7]      Set the clock color                            \n");
    printf("    -b            Use bold colors                                \n");
    printf("    -t            Set the hour in 12h format                     \n");
    printf("    -u            Use UTC time                                   \n");
    printf("    -T tty        Display the clock on the specified terminal    \n");
    printf("    -r            Do rebound the clock                           \n");
    printf("    -f format     Set the date format                            \n");
    printf("    -n            Don't quit on keypress                         \n");
    printf("    -v            Show tty-clock version                         \n");
    printf("    -i            Show some info about tty-clock                 \n");
    printf("    -h            Show this page                                 \n");
    printf("    -D            Hide date                                      \n");
    printf("    -B            Enable blinking colon                          \n");
    printf("    -d delay      Set the delay between two redraws of the clock. Default 1s. \n");
    printf("    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns.\n");
}

static void cleanup_exit(int sig) {
    (void)sig;
    endwin();
    exit(0);
}

static int clock_width(int show_seconds) {
    return show_seconds ? 51 : 32;
}
static int box_w(int show_seconds) {
    return show_seconds ? 54 : 35;
}

int main(int argc, char *argv[]) {
    setlocale(LC_ALL, "");

    int show_seconds = 0;
    int screensaver = 0;
    int show_box = 0;
    int centered = 0;
    int color = 2;
    int bold = 0;
    int twelve_hour = 0;
    int use_utc = 0;
    char *tty_path = NULL;
    int rebound = 0;
    char *date_format = NULL;
    int no_quit = 0;
    int hide_date = 0;
    int blink = 0;
    long delay_sec = 1;
    long delay_nsec = 0;

    int opt;
    // optstring: flags + args
    while ((opt = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
        switch (opt) {
            case 's': show_seconds = 1; break;
            case 'S': screensaver = 1; break;
            case 'x': show_box = 1; break;
            case 'c': centered = 1; break;
            case 'C': {
                int c = atoi(optarg);
                if (c >= 0 && c <= 7) color = c;
                break;
            }
            case 'b': bold = 1; break;
            case 't': twelve_hour = 1; break;
            case 'u': use_utc = 1; break;
            case 'T': {
                struct stat st;
                if (stat(optarg, &st) != 0) {
                    fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", optarg, strerror(errno));
                    return 1;
                }
                if (!S_ISCHR(st.st_mode)) {
                    fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", optarg);
                    return 1;
                }
                int fd = open(optarg, O_RDWR);
                if (fd < 0) {
                    fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s.\n", optarg, strerror(errno));
                    return 1;
                }
                close(fd);
                tty_path = optarg;
                break;
            }
            case 'r': rebound = 1; break;
            case 'f': date_format = optarg; break;
            case 'n': no_quit = 1; break;
            case 'v':
                printf("TTY-Clock 2 \xc2\xa9 devel version\n");
                return 0;
            case 'i':
                printf("TTY-Clock 2 \xc2\xa9 by Martin Duquesnoy (xorg62@gmail.com), Grey (grey@greytheory.net)\n");
                return 0;
            case 'h':
                print_usage();
                return 0;
            case 'D': hide_date = 1; break;
            case 'B': blink = 1; break;
            case 'd': {
                int d = atoi(optarg);
                if (d >= 0) delay_sec = d;
                break;
            }
            case 'a': {
                long a = atol(optarg);
                if (a >= 0 && a < 1000000000L) delay_nsec = a;
                break;
            }
            case '?':
            default:
                print_usage();
                return 0;
        }
    }

    if (date_format == NULL) date_format = "%F";

    if (centered && rebound) {
        rebound = 0;
    }

    // ncurses init
    SCREEN *scr = NULL;
    FILE *tty_in = NULL;
    FILE *tty_out = NULL;
    if (tty_path) {
        tty_in = fopen(tty_path, "r");
        tty_out = fopen(tty_path, "w");
        if (!tty_in || !tty_out) {
            const char *err = strerror(errno);
            // determine which failed? Use generic open error
            fprintf(stderr, "tty-clock: error: '%s' couldn't be opened: %s.\n", tty_path, err);
            return 1;
        }
        scr = newterm(NULL, tty_out, tty_in);
        if (!scr) {
            fprintf(stderr, "Error opening terminal: %s.\n", getenv("TERM") ? getenv("TERM") : "unknown");
            return 1;
        }
        set_term(scr);
    } else {
        initscr();
    }

    signal(SIGINT, cleanup_exit);
    signal(SIGTERM, cleanup_exit);
    signal(SIGHUP, cleanup_exit);
    signal(SIGQUIT, cleanup_exit);

    cbreak();
    noecho();
    curs_set(0);
    keypad(stdscr, TRUE);
    start_color();
    use_default_colors();
    init_pair(1, -1, (short)color);
    init_pair(2, (short)color, -1);

    // timeout based on delay
    long long ms_ll = (long long)delay_sec * 1000LL + (long long)delay_nsec / 1000000LL;
    int ms;
    if (ms_ll < 0) ms = 0;
    else if (ms_ll > 2147483647LL) ms = 2147483647;
    else ms = (int)ms_ll;
    timeout(ms);

    int x = 1, y = 1;
    int dx = 1, dy = 1;
    int show_notch = (centered && show_box) ? 1 : 0;

    // if centered at start and too small? Will be handled in loop (revert to 1,1)
    // main loop
    while (1) {
        int ch = getch();
        if (ch != ERR) {
            if (screensaver) {
                if (ch == KEY_RESIZE) {
                    // fall through to redraw (clear)
                    clear();
                } else {
                    if (!no_quit) break;
                    // else ignore
                }
            } else {
                if (ch == 'q' || ch == 'Q') {
                    if (!no_quit) break;
                } else if (ch == KEY_RESIZE) {
                    clear();
                } else if (ch == 'h' || ch == 'H' || ch == KEY_LEFT) {
                    if (!centered) {
                        int bw = box_w(show_seconds);
                        int max_x = COLS - bw + 1;
                        if (max_x >= 1) {
                            if (x > 1) x--;
                            if (x < 1) x = 1;
                            if (x > max_x) x = max_x;
                        } else {
                            x = 1;
                        }
                        if (show_box) show_notch = 1;
                        else {
                            // notch only relevant with box, but set flag anyway? For future box on? No, box on resets to 0.
                            // For movement without box, notch flag? Keep? Actually movement without box then box on via x gives no notch (since x resets). So don't set here? But movement with box sets.
                            // To match: movement with box sets true. Without box, don't care (will be reset on box on).
                            // However movement without box then s/t? No box, no notch.
                            // So only set when show_box.
                        }
                        // Actually for -x case, movement sets notch. For non-box, irrelevant.
                        // But what about movement without box, then box on? Box on resets to 0, so movement before doesn't matter.
                        // Good.
                    }
                } else if (ch == 'l' || ch == 'L' || ch == KEY_RIGHT) {
                    if (!centered) {
                        int bw = box_w(show_seconds);
                        int max_x = COLS - bw + 1;
                        if (max_x >= 1) {
                            if (x < max_x) x++;
                            if (x < 1) x = 1;
                            if (x > max_x) x = max_x;
                        } else {
                            x = 1;
                        }
                        if (show_box) show_notch = 1;
                    }
                } else if (ch == 'k' || ch == 'K' || ch == KEY_UP) {
                    if (!centered) {
                        int max_y = LINES - 8;
                        if (max_y >= 1) {
                            if (y > 1) y--;
                            if (y < 1) y = 1;
                            if (y > max_y) y = max_y;
                        } else {
                            y = 1;
                        }
                        if (show_box) show_notch = 1;
                    }
                } else if (ch == 'j' || ch == 'J' || ch == KEY_DOWN) {
                    if (!centered) {
                        int max_y = LINES - 8;
                        if (max_y >= 1) {
                            if (y < max_y) y++;
                            if (y < 1) y = 1;
                            if (y > max_y) y = max_y;
                        } else {
                            y = 1;
                        }
                        if (show_box) show_notch = 1;
                    }
                } else if (ch >= '0' && ch <= '7') {
                    color = ch - '0';
                    init_pair(1, -1, (short)color);
                    init_pair(2, (short)color, -1);
                } else if (ch == 'b' || ch == 'B') {
                    bold = !bold;
                } else if (ch == 'x' || ch == 'X') {
                    show_box = !show_box;
                    if (show_box) {
                        show_notch = 0;
                        // clamp x,y to new bounds? When enabling box, bounds same (since bounds already consider box), so no clamp needed.
                        // But when box width? Bounds same with/without box (since always consider box), so no change.
                    }
                } else if (ch == 'c' || ch == 'C') {
                    centered = !centered;
                    if (centered) {
                        rebound = 0;
                        if (show_box) show_notch = 1;
                    } else {
                        // turning off: keep rebound off, keep notch as is (stays true if was true)
                    }
                } else if (ch == 'r' || ch == 'R') {
                    rebound = !rebound;
                    if (rebound) {
                        centered = 0;
                        if (show_box) show_notch = 1;
                    }
                } else if (ch == 's' || ch == 'S') {
                    show_seconds = !show_seconds;
                    if (show_box) show_notch = 1;
                    // clamp x if exceeds new max?
                    {
                        int bw = box_w(show_seconds);
                        int max_x = COLS - bw + 1;
                        if (max_x >= 1) {
                            if (x > max_x) x = max_x;
                            if (x < 1) x = 1;
                        } else {
                            x = 1;
                        }
                    }
                    // update timeout? delay unchanged, no need. But ms same.
                } else if (ch == 't' || ch == 'T') {
                    twelve_hour = !twelve_hour;
                    if (show_box) show_notch = 1;
                } else {
                    // ignore other keys (including 8,9, etc.)
                }
            }
        }

        // update position for centered/rebound
        if (centered) {
            int cw = clock_width(show_seconds);
            int bw = box_w(show_seconds);
            if (COLS < bw || LINES < 7) {
                x = 1; y = 1;
            } else {
                int cx = (COLS - cw) / 2;
                int cy = (LINES - 4) / 2;
                x = cx; y = cy;
            }
        } else if (rebound) {
            int bw = box_w(show_seconds);
            int max_x = COLS - bw + 1;
            int max_y = LINES - 8;
            if (max_x < 1 || max_y < 1) {
                x = 1; y = 1;
            } else {
                // clamp current if out of bounds (e.g., after resize or seconds toggle)?
                if (x < 1) x = 1;
                if (x > max_x) x = max_x;
                if (y < 1) y = 1;
                if (y > max_y) y = max_y;
                int nx = x + dx;
                int ny = y + dy;
                if (nx < 1 || nx > max_x) {
                    dx = -dx;
                    nx = x + dx;
                    if (nx < 1) nx = 1;
                    if (nx > max_x) nx = max_x;
                }
                if (ny < 1 || ny > max_y) {
                    dy = -dy;
                    ny = y + dy;
                    if (ny < 1) ny = 1;
                    if (ny > max_y) ny = max_y;
                }
                x = nx; y = ny;
                if (show_box) show_notch = 1;
            }
        } else {
            // manual: clamp to bounds (in case of resize making current out of bounds? Original leaves out-of-bounds on resize (clipped), not clamp. So don't clamp here.
            // Only clamp on movement keys (already done) and on seconds toggle (done).
            // Do nothing.
        }

        // get time
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *tm;
        if (use_utc) {
            tm = gmtime_r(&now, &tm_buf);
            if (!tm) tm = gmtime(&now);
        } else {
            tm = localtime_r(&now, &tm_buf);
            if (!tm) tm = localtime(&now);
        }
        int hour = tm->tm_hour;
        int min = tm->tm_min;
        int sec = tm->tm_sec;
        int disp_hour = hour;
        const char *ampm = NULL;
        if (twelve_hour) {
            ampm = (hour < 12) ? "AM" : "PM";
            disp_hour = hour % 12;
            if (disp_hour == 0) disp_hour = 12;
        }
        int h0 = disp_hour / 10;
        int h1 = disp_hour % 10;
        int m0 = min / 10;
        int m1 = min % 10;
        int s0 = sec / 10;
        int s1 = sec % 10;

        int colon_on = 1;
        if (blink) {
            colon_on = (sec % 2 == 1) ? 1 : 0;
        }

        // date string
        char date_buf[512];
        char date_final[560];
        date_buf[0] = '\0';
        date_final[0] = '\0';
        size_t dl = 0;
        if (!hide_date) {
            strftime(date_buf, sizeof(date_buf), date_format, tm);
            if (twelve_hour) {
                // append " [AM]" / " [PM]"
                snprintf(date_final, sizeof(date_final), "%s [%s]", date_buf, ampm);
            } else {
                snprintf(date_final, sizeof(date_final), "%s", date_buf);
            }
            dl = strlen(date_final);
        } else {
            dl = 0;
            date_final[0] = '\0';
        }
        int W = show_seconds ? 53 : 33;
        int show_date = 0;
        int date_x = 0, date_y = 0;
        if (!hide_date && dl > 0 && (int)dl <= W) {
            show_date = 1;
            date_x = x + (W - (int)dl) / 2;
            date_y = y + 6;
        } else {
            show_date = 0;
        }

        erase();

        // draw clock digits
        // helper to draw a digit at (dx,dy)
        // positions
        int dxs[6];
        int n_digits = show_seconds ? 6 : 4;
        int digits[6];
        if (show_seconds) {
            digits[0]=h0; digits[1]=h1; digits[2]=m0; digits[3]=m1; digits[4]=s0; digits[5]=s1;
            dxs[0]=x+0; dxs[1]=x+7; dxs[2]=x+19; dxs[3]=x+26; dxs[4]=x+38; dxs[5]=x+45;
        } else {
            digits[0]=h0; digits[1]=h1; digits[2]=m0; digits[3]=m1;
            dxs[0]=x+0; dxs[1]=x+7; dxs[2]=x+19; dxs[3]=x+26;
        }
        for (int di=0; di<n_digits; di++) {
            int d = digits[di];
            int bx = dxs[di];
            for (int r=0;r<5;r++) {
                for (int c=0;c<6;c++) {
                    int sx = bx + c;
                    int sy = y + r;
                    if (sx < 0 || sy < 0 || sx >= COLS || sy >= LINES) continue;
                    char fc = font[d][r][c];
                    if (fc == 'X') {
                        if (bold) attron(COLOR_PAIR(1) | A_BLINK);
                        else attron(COLOR_PAIR(1));
                        mvaddch(sy, sx, ' ');
                        if (bold) attroff(COLOR_PAIR(1) | A_BLINK);
                        else attroff(COLOR_PAIR(1));
                    } else {
                        if (bold) {
                            attron(A_BLINK);
                            mvaddch(sy, sx, ' ');
                            attroff(A_BLINK);
                        } else {
                            // already blank due to erase, no need to draw? But to ensure overwrite of previous? erase already cleared. Skip.
                            // mvaddch(sy,sx,' ');
                        }
                    }
                }
            }
        }
        // draw colons
        int colon_x[2];
        int n_colons = show_seconds ? 2 : 1;
        if (show_seconds) { colon_x[0]=x+13; colon_x[1]=x+32; }
        else { colon_x[0]=x+13; }
        if (colon_on) {
            for (int ci=0; ci<n_colons; ci++) {
                int bx = colon_x[ci];
                // rows 1 and 3, cols 2-3
                for (int r=0;r<5;r++) {
                    for (int c=0;c<6;c++) {
                        int is_dot = 0;
                        if ((r==1 || r==3) && (c==2 || c==3)) is_dot=1;
                        if (!is_dot) continue; // padding, already blank
                        int sx = bx + c;
                        int sy = y + r;
                        if (sx<0||sy<0||sx>=COLS||sy>=LINES) continue;
                        if (bold) attron(COLOR_PAIR(1) | A_BLINK);
                        else attron(COLOR_PAIR(1));
                        mvaddch(sy,sx,' ');
                        if (bold) attroff(COLOR_PAIR(1) | A_BLINK);
                        else attroff(COLOR_PAIR(1));
                    }
                }
            }
        } else {
            // off: nothing to draw (already blank)
        }

        // draw date
        if (show_date) {
            if (bold) attron(COLOR_PAIR(2) | A_BOLD);
            else attron(COLOR_PAIR(2));
            // mvaddstr will clip if exceeds? Ensure no wrap: use mvaddnstr with limit?
            // Find max len that fits: if date_x<0, need to offset? Original with negative date_x doesn't draw at all (since len>W fails, date_x>=1). But with resize, date_x may be out of bounds? E.g., clock at (46,16) in 80x24, date at 57? Fits. After resize to 50x15, clock at (46,16) out of bounds, date at 57? Off-screen, mvaddstr with x>=COLS returns ERR, no crash. Good. Just call mvaddstr, it will handle clipping/ERR.
            // However if date_x<0 (e.g., long date? But we already check len<=W, date_x>=1? For centered? date_x>=? Could be negative when clock at 1 and date long? For len=33, date_x=1, ok. For len<=W, date_x>=1? Since x>=1 and (W-len)>=0, date_x>=1. Good. So date_x>=1 always when show_date. Good. No negative.
            // But when clock out-of-bounds due to resize (x=46 in 50-wide? Actually 46+? exceeds? date_x=57>50, off-screen, mvaddstr will fail gracefully.
            mvaddstr(date_y, date_x, date_final);
            if (bold) attroff(COLOR_PAIR(2) | A_BOLD);
            else attroff(COLOR_PAIR(2));
        }

        // draw boxes
        if (show_box) {
            int bw = box_w(show_seconds);
            int bh = 7;
            int bx = x - 1;
            int by = y - 1;
            // top
            if (by >= 0 && by < LINES) {
                if (bx >=0 && bx < COLS) mvaddch(by, bx, ACS_ULCORNER);
                for (int i=1;i<bw-1;i++) {
                    int sx=bx+i;
                    if (sx>=0&&sx<COLS) mvaddch(by, sx, ACS_HLINE);
                }
                if (bx+bw-1>=0 && bx+bw-1<COLS) mvaddch(by, bx+bw-1, ACS_URCORNER);
            }
            // sides
            for (int r=1;r<bh-1;r++) {
                int sy=by+r;
                if (sy<0||sy>=LINES) continue;
                if (bx>=0&&bx<COLS) mvaddch(sy, bx, ACS_VLINE);
                if (bx+bw-1>=0&&bx+bw-1<COLS) mvaddch(sy, bx+bw-1, ACS_VLINE);
            }
            // bottom
            int bby=by+bh-1;
            if (bby>=0&&bby<LINES) {
                if (bx>=0&&bx<COLS) mvaddch(bby, bx, ACS_LLCORNER);
                for (int i=1;i<bw-1;i++) {
                    int sx=bx+i;
                    if (sx>=0&&sx<COLS) mvaddch(bby, sx, ACS_HLINE);
                }
                if (bx+bw-1>=0&&bx+bw-1<COLS) mvaddch(bby, bx+bw-1, ACS_LRCORNER);
            }
            // date box
            if (show_date) {
                int dbw = (int)dl + 2;
                int dbx = date_x - 1;
                int dtop = date_y - 1;
                int dmid = date_y;
                int dbot = date_y + 1;
                // sides at dmid
                if (dmid>=0&&dmid<LINES) {
                    if (dbx>=0&&dbx<COLS) mvaddch(dmid, dbx, ACS_VLINE);
                    if (dbx+dbw-1>=0&&dbx+dbw-1<COLS) mvaddch(dmid, dbx+dbw-1, ACS_VLINE);
                }
                // bottom at dbot
                if (dbot>=0&&dbot<LINES) {
                    if (dbx>=0&&dbx<COLS) mvaddch(dbot, dbx, ACS_LLCORNER);
                    for (int i=1;i<dbw-1;i++) {
                        int sx=dbx+i;
                        if (sx>=0&&sx<COLS) mvaddch(dbot, sx, ACS_HLINE);
                    }
                    if (dbx+dbw-1>=0&&dbx+dbw-1<COLS) mvaddch(dbot, dbx+dbw-1, ACS_LRCORNER);
                }
                // top at dtop (notch) only if show_notch
                if (show_notch) {
                    if (dtop>=0&&dtop<LINES) {
                        if (dbx>=0&&dbx<COLS) mvaddch(dtop, dbx, ACS_ULCORNER);
                        for (int i=1;i<dbw-1;i++) {
                            int sx=dbx+i;
                            if (sx>=0&&sx<COLS) mvaddch(dtop, sx, ACS_HLINE);
                        }
                        if (dbx+dbw-1>=0&&dbx+dbw-1<COLS) mvaddch(dtop, dbx+dbw-1, ACS_URCORNER);
                    }
                }
                // need to redraw date text after box? Since box sides at same row as date but different cols (no overlap), order doesn't matter. But date top/bottom at different rows, no overlap with date text. Good. However date box sides at dmid overlap? No, date text at date_x..date_x+dl-1, sides at date_x-1 and date_x+dl, no overlap. Good.
                // But clock box bottom (at bby) overlaps date top (at dtop) when show_notch? Since dtop==bby? Let's verify: bby=by+6=(y-1)+6=y+5. dtop=date_y-1=(y+6)-1=y+5. Yes same! Good. So date top overwrites clock bottom (notch). Since we draw clock box first, then date top, overwrites correctly. Good.
                // When show_notch==0, date top not drawn, clock bottom remains. Good.
            }
        }

        refresh();
    }

    endwin();
    if (tty_in) fclose(tty_in);
    if (tty_out) fclose(tty_out);
    return 0;
}
