static time_t get_fake(time_t *is_fake) {
    const char *s = getenv("FAKE_TIME");
    if (s && *s) { *is_fake=1; return (time_t)atoll(s); }
    *is_fake=0; return 0;
}

time_t time(time_t *t) {
    time_t is_fake; time_t ft = get_fake(&is_fake);
    if (is_fake) { if (t) *t=ft; return ft; }
    time_t (*real_time)(time_t*) = dlsym(RTLD_NEXT, "time");
    return real_time(t);
}
