            if (tp) { tp->tv_sec = ft; tp->tv_nsec = 0; }
            return 0;
        }
    }
    int (*real_cg)(clockid_t, struct timespec*) = dlsym(RTLD_NEXT, "clock_gettime");
    return real_cg(clk, tp);
}
